pub fn _HSD_TObjGetCurrentByType<'a>(
    ctx: &'a Ctx,
    from: HSD_TObj<'a>,
    mapping: u32,
) -> HSD_TObj<'a> {
    let mut from = from;
    let mut mapping = mapping;
    let mut tp: HSD_TObj<'a> = null(ctx);
    'goto_END: {
        if Handle::is_null(from) {
            tp = fns::tobj_head(ctx).get();
        } else {
            tp = (from).next();
        }
        {
            'l1: while !Handle::is_null(tp) {
                'c2: {
                    if ((tp).flags() & ((15_i32) as u32)) == mapping {
                        break 'goto_END;
                    }
                }
                tp = (tp).next();
            }
        }
        tp = null::<HSD_TObj<'a>>(ctx);
    }
    return tp;
    #[allow(unreachable_code)]
    return null(ctx);
}

pub fn HSD_TexMapID2PTTexMtx<'a>(ctx: &'a Ctx, id: i32) -> u32 {
    let __frame = ctx.stack_frame(0x8);
    let mut id = id;
    's1: {
        let __case = match (id as u32) {
            0_u32 => 0,
            1_u32 => 1,
            2_u32 => 2,
            3_u32 => 3,
            4_u32 => 4,
            5_u32 => 5,
            6_u32 => 6,
            7_u32 => 7,
            _ => 8,
        };
        if __case <= 0 {
            return ((enums::GX_PTTEXMTX0 as i32) as u32);
        }
        if __case <= 1 {
            return ((enums::GX_PTTEXMTX1 as i32) as u32);
        }
        if __case <= 2 {
            return ((enums::GX_PTTEXMTX2 as i32) as u32);
        }
        if __case <= 3 {
            return ((enums::GX_PTTEXMTX3 as i32) as u32);
        }
        if __case <= 4 {
            return ((enums::GX_PTTEXMTX4 as i32) as u32);
        }
        if __case <= 5 {
            return ((enums::GX_PTTEXMTX5 as i32) as u32);
        }
        if __case <= 6 {
            return ((enums::GX_PTTEXMTX6 as i32) as u32);
        }
        if __case <= 7 {
            return ((enums::GX_PTTEXMTX7 as i32) as u32);
        }
        if __case <= 8 {
            fns::HSD_Panic(
                ctx,
                cstr(ctx, 0x80405574),
                (0x23e_i32 as u32),
                cstr(ctx, 0x8040562c),
            );
        }
    }
    return (0_i32 as u32);
}

pub fn MakeTextureMtx<'a>(ctx: &'a Ctx, tobj: HSD_TObj<'a>) {
    let __frame = ctx.stack_frame(0x98);
    let scale: Vec<'a> = frame_at(ctx, &__frame, 0x0);
    let m: Arr<'a, ArrV<'a, F32, 4>, 3> = frame_at(ctx, &__frame, 0x28);
    let trans: Vec<'a> = frame_at(ctx, &__frame, 0x1c);
    let rot: Quaternion<'a> = frame_at(ctx, &__frame, 0xc);
    let mut tobj = tobj;
    'l1: loop {
        'c2: {}
        if !(0_i32 != 0) {
            break 'l1;
        }
    }
    (if (((tobj).repeat_s() as i32) != 0) && (((tobj).repeat_t() as i32) != 0) {
        ({ () })
    } else {
        fns::__assert(
            ctx,
            cstr(ctx, 0x80405574),
            (0x24d_i32 as u32),
            cstr(ctx, 0x80405574),
        )
    });
    scale.set_x(
        (if fp::fabs((tobj).scale().x()) < 1.000000013351432e-10_f64 {
            0.0
        } else {
            fp::fdivs(fp::frsp((tobj).repeat_s() as f64), (tobj).scale().x())
        }),
    );
    scale.set_y(
        (if fp::fabs((tobj).scale().y()) < 1.000000013351432e-10_f64 {
            0.0
        } else {
            fp::fdivs(fp::frsp((tobj).repeat_t() as f64), (tobj).scale().y())
        }),
    );
    scale.set_z((tobj).scale().z());
    rot.set_x((tobj).rotate().x());
    rot.set_y((tobj).rotate().y());
    rot.set_z(fp::fneg((tobj).rotate().z()));
    trans.set_x(fp::fneg((tobj).translate().x()));
    trans.set_y(fp::fneg(
        (fp::fadds(
            (tobj).translate().y(),
            (if (tobj).wrap_t() == (((enums::GX_MIRROR as i32) as u32) as i32) {
                fp::fdivs(
                    1.0,
                    (fp::fdivs(
                        fp::frsp(((tobj).repeat_t() as i32) as f64),
                        (tobj).scale().y(),
                    )),
                )
            } else {
                0.0
            }),
        )),
    ));
    trans.set_z((tobj).translate().z());
    fns::PSMTXTrans(ctx, (tobj).mtx().get(0), trans.x(), trans.y(), trans.z());
    fns::HSD_MkRotationMtx(ctx, m.get(0), Handle::cast::<Vec<'a>>(rot));
    fns::PSMTXConcat(ctx, m.get(0), (tobj).mtx().get(0), (tobj).mtx().get(0));
    fns::PSMTXScale(ctx, m.get(0), scale.x(), scale.y(), scale.z());
    fns::PSMTXConcat(ctx, m.get(0), (tobj).mtx().get(0), (tobj).mtx().get(0));
}

